using System;using System.Data.SqlClient;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class OfferApprovalPage:UserControl{DataGridView grid;public OfferApprovalPage(){BackColor=Theme.Background;var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=55};var approve=Ui.Button(L.Fa?"تایید":"Approve");var reject=Ui.Button(L.Fa?"رد":"Reject",false);var send=Ui.Button(L.Fa?"ارسال برای تایید":"Submit for approval",false);approve.Click+=(s,e)=>Set("Approved");reject.Click+=(s,e)=>Set("Rejected");send.Click+=(s,e)=>Set("PendingApproval");bar.Controls.Add(approve);bar.Controls.Add(reject);bar.Controls.Add(send);grid=Ui.Grid();Controls.Add(grid);Controls.Add(bar);grid.BringToFront();LoadData();}void LoadData(){grid.DataSource=Database.Query("SELECT o.Id,c.FullName AS Candidate,j.Title AS Job,o.Salary,o.StartDate,o.ExpiryDate,o.Status,o.CreatedAt FROM Offers o JOIN Applications a ON a.Id=o.ApplicationId JOIN Candidates c ON c.Id=a.CandidateId JOIN Jobs j ON j.Id=a.JobId ORDER BY CASE o.Status WHEN 'PendingApproval' THEN 0 ELSE 1 END,o.CreatedAt DESC");}void Set(string status){if(grid.CurrentRow==null)return;int id=Convert.ToInt32(grid.CurrentRow.Cells["Id"].Value);Database.Exec("UPDATE Offers SET Status=@s WHERE Id=@i",new SqlParameter("@s",status),new SqlParameter("@i",id));Database.Audit("OfferStatus","Offer",id+" -> "+status);LoadData();}}}